"""Check UI symbols generated by the engine, outside translated text tables.

The four targeting triangles are passed to the native text renderer by
the Steam executable (live code at VA 0x5022F1..0x50243F). U+00AB is
an upward triangle in the original game atlas, not a quotation mark.
"""
import argparse
import json
import sys
from pathlib import Path

from ua.formats.fnt import FntFile

ROOT = Path(__file__).resolve().parents[2]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))
from ua import paths  # noqa: E402
TARGETING = {
    0x00AB: "bottom marker (upward triangle)",
    0x00A3: "top marker (downward triangle)",
    0x003E: "left marker (rightward triangle)",
    0x003C: "right marker (leftward triangle)",
}


def audit(path):
    font = FntFile(str(path))
    mapping = {entry.codepoint: entry.glyph_index for entry in font.list_mapping()}
    return {
        "font": str(path),
        "targeting": [
            {"codepoint": f"U+{cp:04X}", "role": role,
             "glyph_index": mapping.get(cp), "present": cp in mapping}
            for cp, role in TARGETING.items()
        ],
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("font", nargs="?", type=Path,
                        default=paths.BUILD / "uap-unpacked/STUFF/TEXT/FONT_PC.FNT")
    args = parser.parse_args()
    report = audit(args.font)
    print(json.dumps(report, indent=2))
    raise SystemExit(0 if all(item["present"] for item in report["targeting"]) else 1)
